"""Hip hop: boom bap on the 808 and a piano. python3 scripts/packgen/hip_hop.py"""
import sys, os
sys.path.insert(0, os.path.dirname(__file__))
from common import *  # noqa: F401,F403

T = 'setcpm(90/4)'
KICK = 'const kick = s("bd ~ ~ ~ ~ ~ bd ~").bank("RolandTR808")'
SNARE = 'const snare = s("~ sd ~ sd").bank("RolandTR808")'
HATS = 'const hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4").swingBy(.2, 8)'
SUB = 'const sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale("C1:minor").s("sine").release(.6).gain(.8)'
KEYS = 'const keys = chord("Cm7").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").clip(.4).room(.3).gain(.5)'
GHOST = 'const kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1").swingBy(.2, 8)'

HALF_TIME = [0, 0.75]
SIX_EIGHT = 1 / 16  # second 16th, straight

lessons = [
    lesson('half-time', 'Half-time', 'Lay down the boom bap: kick on 1 and the "and" of 3, snare on 2 and 4, at 90 BPM.',
           'Hip hop drums came from drum breaks chopped on an **SP-1200** or an **MPC**, and the pattern underneath most of them is **boom bap**: a kick (boom) on beat 1, a snare (bap) on 2 and 4, and a second kick pushed to the "and" of 3. At 90 BPM the groove feels **half-time**, like it’s leaning back.\n\nWrite the kick over 8ths: `"bd ~ ~ ~ ~ ~ bd ~"` is eight steps, so the second kick lands halfway through beat 4’s run-up, on the "and" of 3. The TR-808 gives the deep, round boom. There are no vocal samples here, so these beats stay instrumental.',
           f'{T}\n',
           [task('A part called kick: TR-808, on beat 1 and the "and" of 3, written over 8ths.',
                 'const kick = s("bd ~ ~ ~ ~ ~ bd ~").bank("RolandTR808"), then stack(kick).',
                 all_(defines('kick'), playsAt('bd', HALF_TIME), every(snd('bd'), w('bank', eq=TR808)))),
            task('A part called snare on beats 2 and 4, and stack it.',
                 'const snare = s("~ sd ~ sd").bank("RolandTR808")',
                 all_(defines('snare'), playsAt('sd', [0.25, 0.75])), replacedLater=True)],
           [f'{T}\n{KICK}\nstack(kick)'],
           f'{T}\n{KICK}\n{SNARE}\nstack(kick, snare)', ['B4', 'B5', 'B1'], ['drums', '808'],
           challenge=task('Add a second snare hit: a quiet one on the last 16th of the bar.',
                          'const snare = s("~ sd ~ [sd ~ ~ sd]").bank("RolandTR808").gain("1 1 1 [1 1 1 .4]")',
                          all_(includesTimes('sd', [0.25, 0.75, 0.9375]), some(snd('sd'), w('gain', lt=0.6, default=1)))),
           challengeSolution=f'{T}\n{KICK}\nconst snare = s("~ sd ~ [sd ~ ~ sd]").bank("RolandTR808").gain("1 1 1 [1 1 1 .4]")\nstack(kick, snare)',
           summary=['Boom bap: kick on 1 and the "and" of 3, snare on 2 and 4.', 'Writing over 8ths ("bd ~ ~ ~ ~ ~ bd ~") places the second kick.', '90 BPM feels half-time: laid back.'],
           introduces=['s', '.bank', 'stack'], concepts=['boom bap', 'half-time'],
           preload=kit('bd', 'sd', bank=TR808)),

    lesson('swung-hats', 'Swung hats', 'Add 16th hats with a heavy swing and a gain pattern.',
           'Swing is what separates a hip hop beat from a drum machine preset. The MPC’s swing setting pushed every second 16th late; **DJ Premier** kept it tight, **J Dilla** pushed it until the hats sounded drunk. Here `.swingBy(.2, 8)` is about 60% swing: lazy but still locked.\n\nA **gain pattern** keeps the hats from sounding like a sewing machine: the hit on the beat loud, the ones between quiet. `"[.5 .25 .35 .25]*4"` lines up with `hh*16`, one value per hat.',
           f'{T}\n{KICK}\n{SNARE}\nstack(kick, snare)',
           [task('A part called hats: 16th closed hats on the 808, with the hit on each beat loudest.',
                 'const hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4"), and stack it.',
                 all_(defines('hats'), eq(count(s='hh'), 16),
                      gt(valueAt(snd('hh'), 'gain', index=0, default=0.8), valueAt(snd('hh'), 'gain', index=1, default=0.8)))),
            task('Swing them hard: about 60%.',
                 '.swingBy(.2, 8) on the hats line.',
                 all_(eq(count(s='hh'), 16), gte(timeAt(snd('hh'), 1), SIX_EIGHT + 0.15 / 16), lte(timeAt(snd('hh'), 1), SIX_EIGHT + 0.3 / 16)))],
           [f'{T}\n{KICK}\n{SNARE}\nconst hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4")\nstack(kick, snare, hats)'],
           f'{T}\n{KICK}\n{SNARE}\n{HATS}\nstack(kick, snare, hats)', ['I1', 'I4', 'B3'], ['drums', 'swing', '808'],
           challenge=task('Open a hat on the "and" of 4, right before the bar turns around.',
                          'const open = s("~ ~ ~ [~ oh]").bank("RolandTR808").gain(.4), and stack it.',
                          all_(playsAt('oh', [0.875]), every(snd('oh'), w('gain', lt=0.6, default=0.8)))),
           challengeSolution=f'{T}\n{KICK}\n{SNARE}\n{HATS}\nconst open = s("~ ~ ~ [~ oh]").bank("RolandTR808").gain(.4)\nstack(kick, snare, hats, open)',
           summary=['.swingBy(.2, 8) is about 60% swing: the Dilla lean.', 'A gain pattern on 16th hats puts the weight on the beat.', 'An open hat on the "and" of 4 marks the turnaround.'],
           introduces=['.swingBy', 'patterned .gain'], concepts=['swing'],
           preload=kit('bd', 'sd', 'hh', 'oh', bank=TR808)),

    lesson('the-808-sub', 'The 808 sub', 'Put a long sine bass under the kick, in a key.',
           'The **808 bass** is the kick drum’s long tail turned into a note: a pure sine, low, that rings out. In Strudel we build it from `s("sine")` with a slow `.release`, so each note hangs after it’s struck.\n\nIt plays on the kick’s rhythm, so the boom and the bass become one sound. `n("0 ~ ~ ~ ~ ~ 0 ~").scale("C1:minor")` picks scale degrees in the first octave: the 1 in the scale name is what makes it a sub. Keep it low in the mix: on laptop speakers you may barely hear it, but on anything with a woofer it’s the whole beat.',
           f'{T}\n{KICK}\n{SNARE}\n{HATS}\nstack(kick, snare, hats)',
           [task('A part called sub: a sine playing scale degree 0 of C1 minor on the kick’s rhythm.',
                 'const sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale("C1:minor").s("sine"), and stack it.',
                 all_(defines('sub'), playsAt(None, HALF_TIME, cycles=1, sel=snd('sine')),
                      every(snd('sine'), w('$midi', lt=36)))),
            task('Let it ring: a release of about half a second, and gain .8.',
                 '.release(.6).gain(.8) on the sub line.',
                 every(snd('sine'), w('release', gte=0.4, default=0), w('gain', lte=0.9, gte=0.6, default=0.8)))],
           [f'{T}\n{KICK}\n{SNARE}\n{HATS}\nconst sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale("C1:minor").s("sine")\nstack(kick, snare, hats, sub)'],
           f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\nstack(kick, snare, hats, sub)', ['B12', 'I10', 'I5'], ['bass', '808'],
           challenge=task('Move the second note to degree 2 (the flat third) so the bass walks.',
                          'n("0 ~ ~ ~ ~ ~ 2 ~")',
                          all_(some(snd('sine'), w('$pc', eq=0)), some(snd('sine'), w('$pc', eq=3)))),
           challengeSolution=f'{T}\n{KICK}\n{SNARE}\n{HATS}\nconst sub = n("0 ~ ~ ~ ~ ~ 2 ~").scale("C1:minor").s("sine").release(.6).gain(.8)\nstack(kick, snare, hats, sub)',
           summary=['An 808 bass is a low sine with a long release.', 'scale("C1:minor"): the 1 puts the notes in the sub octave.', 'Play it on the kick’s rhythm so boom and bass are one sound.'],
           introduces=['n', '.scale', '.release', 'sine'], concepts=['the 808 bass'],
           preload=kit('bd', 'sd', 'hh', bank=TR808)),

    lesson('piano-chops', 'Piano chops', 'Chop a piano chord into a syncopated stab.',
           'Boom bap was built on **chopped samples**: a bar of a soul record, cut into pieces on the SP-1200 and replayed off the pads. We have no records to chop, but the move translates: a sampled piano chord, cut short with `.clip`, placed on an off-grid rhythm with `.struct`.\n\n`.struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]")` writes two hits per two beats, neither on the beat. `.clip(.4)` cuts each hit to 40% of its step, like lifting a finger off a pad. A little `.room` puts the piano on a dusty record instead of in the room with you.',
           f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\nstack(kick, snare, hats, sub)',
           [task('A part called keys: a Cm7 piano chord struck on the 2nd 16th of beat 1 and the 3rd 16th of beat 2 (then again in beats 3 and 4).',
                 'const keys = chord("Cm7").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").gain(.5), and stack it.',
                 all_(defines('keys'), gte(CHORD_SIZE, 3),
                      eq(values(snd('piano'), '$time', unique=True, sorted=True), [0.0625, 0.375, 0.5625, 0.875]))),
            task('Cut each hit short, like a pad release: clip .4.',
                 '.clip(.4) on the keys line.',
                 every(snd('piano'), w('clip', lte=0.5, default=1))),
            task('Put it on a dusty record: a little reverb.',
                 '.room(.3) on the keys line.',
                 every(snd('piano'), w('room', gt=0, default=0)))],
           [f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\nconst keys = chord("Cm7").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").gain(.5)\nstack(kick, snare, hats, sub, keys)',
            f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\nconst keys = chord("Cm7").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").clip(.4).gain(.5)\nstack(kick, snare, hats, sub, keys)'],
           f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\n{KEYS}\nstack(kick, snare, hats, sub, keys)', ['I6', 'I20', 'I14'], ['piano', 'chords'],
           challenge=task('Alternate two chords across bars: Cm7, then Fm7.',
                          'chord("<Cm7 Fm7>")',
                          neq(values(snd('piano', bar=0), '$pc', unique=True, sorted=True), values(snd('piano', bar=1), '$pc', unique=True, sorted=True))),
           challengeSolution=f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\nconst keys = chord("<Cm7 Fm7>").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").clip(.4).room(.3).gain(.5)\nstack(kick, snare, hats, sub, keys)',
           summary=['.struct places a chord off the grid, like pads on an SP-1200.', '.clip(.4) cuts each hit short.', 'A touch of .room makes a piano sound sampled.'],
           introduces=['chord', '.voicing', '.struct', '.clip', '.room'], concepts=['chops'],
           preload=kit('bd', 'sd', 'hh', bank=TR808) + [{"s": "piano"}]),

    lesson('ghost-kicks', 'Ghost kicks and the drunken feel', 'Add a quiet extra kick and swing the kick itself.',
           'Listen to a Dilla beat and the kick never sits exactly where a drum machine would put it. Two things are going on: **ghost kicks**, quiet extra hits that fill the gaps, and **swing on the kick**, not only on the hats, so the whole kit leans together.\n\n`"bd ~ ~ [~ bd] ~ ~ bd ~"` adds a kick on the last 16th of beat 2; a gain pattern with a `.3` in that slot makes it a ghost. Then `.swingBy(.2, 8)` on the kick line pushes it the same way as the hats. The snare stays straight: that’s the tension that makes it feel drunk rather than sloppy.',
           f'{T}\n{KICK}\n{SNARE}\n{HATS}\n{SUB}\n{KEYS}\nstack(kick, snare, hats, sub, keys)',
           [task('Add a ghost kick on the last 16th of beat 2, at gain .3.',
                 'const kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1")',
                 all_(eq(count(s='bd'), 3), some(snd('bd'), w('gain', lt=0.5, default=1)),
                      includesTimes('bd', [0, 0.75]))),
            task('Swing the kick like the hats.',
                 'Add .swingBy(.2, 8) to the kick line.',
                 all_(eq(count(s='bd'), 3), gt(timeAt(snd('bd'), 1), 0.4375 + 0.01)))],
           [f'{T}\nconst kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1")\n{SNARE}\n{HATS}\n{SUB}\n{KEYS}\nstack(kick, snare, hats, sub, keys)'],
           f'{T}\n{GHOST}\n{SNARE}\n{HATS}\n{SUB}\n{KEYS}\nstack(kick, snare, hats, sub, keys)', ['I4', 'I1', 'I2'], ['drums', 'swing'],
           challenge=task('Drop the first kick every fourth bar, so the loop breathes.',
                          'Add .lastOf(4, x => x.mask("0 1 1 1 1 1 1 1")) to the kick line.',
                          all_(eq(count(s='bd', bar=0), 3), eq(count(s='bd', bar=3), 2), eq(count(s='bd', bar=3, at=0), 0))),
           challengeSolution=f'{T}\n{GHOST}.lastOf(4, x => x.mask("0 1 1 1 1 1 1 1"))\n{SNARE}\n{HATS}\n{SUB}\n{KEYS}\nstack(kick, snare, hats, sub, keys)',
           summary=['Ghost kicks are quiet extra hits in the gaps.', 'Swinging the kick as well as the hats gives the drunken feel.', 'Keep the snare straight: the tension is the point.'],
           introduces=['patterned .gain', '.lastOf', '.mask'], concepts=['ghost notes'],
           preload=kit('bd', 'sd', 'hh', bank=TR808) + [{"s": "piano"}]),

    lesson('the-beat', 'Project: The beat', 'Build a boom bap beat from scratch with one key for everything.',
           'Everything from this pack in one loop: the half-time kick with a ghost, a straight snare, swung hats, the 808 sub and piano chops, all in one key. A `const key` at the top keeps the sub and the piano agreeing, and makes a different key a one-line change.\n\nAim for 88–95 BPM. Keep the piano and sub under the drums: the kick and snare are the record; everything else is the sample around them.',
           'setcpm(92/4)\nconst key = "C:minor"\nconst kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1").swingBy(.2, 8)\nconst snare = s("~ sd ~ sd").bank("RolandTR808")\nstack(kick, snare)',
           [task('Add swung 16th hats with a gain pattern.',
                 'const hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4").swingBy(.2, 8), and stack it.',
                 all_(defines('hats'), eq(count(s='hh'), 16), gte(timeAt(snd('hh'), 1), SIX_EIGHT + 0.1 / 16))),
            task('Add the 808 sub in the key, on the kick’s two main hits, ringing out.',
                 'const sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale(key).s("sine").octave(1).release(.6).gain(.8)',
                 all_(defines('sub'), inKey(sel=snd('sine')), playsAt(None, HALF_TIME, cycles=1, sel=snd('sine')),
                      every(snd('sine'), w('release', gte=0.4, default=0)))),
            task('Add piano chops in the key: a chord stab, clipped short, with a little room, under gain .6.',
                 'const keys = chord("<Cm7 Fm7>").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").clip(.4).room(.3).gain(.5)',
                 all_(defines('keys'), gte(CHORD_SIZE, 3), every(snd('piano'), w('clip', lte=0.5, default=1), w('room', gt=0, default=0), w('gain', lte=0.6, default=0.8))))],
           ['setcpm(92/4)\nconst key = "C:minor"\nconst kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1").swingBy(.2, 8)\nconst snare = s("~ sd ~ sd").bank("RolandTR808")\nconst hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4").swingBy(.2, 8)\nstack(kick, snare, hats)',
            'setcpm(92/4)\nconst key = "C:minor"\nconst kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1").swingBy(.2, 8)\nconst snare = s("~ sd ~ sd").bank("RolandTR808")\nconst hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4").swingBy(.2, 8)\nconst sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale(key).s("sine").octave(1).release(.6).gain(.8)\nstack(kick, snare, hats, sub)'],
           'setcpm(92/4)\nconst key = "C:minor"\nconst kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1").swingBy(.2, 8)\nconst snare = s("~ sd ~ sd").bank("RolandTR808")\nconst hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4").swingBy(.2, 8)\nconst sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale(key).s("sine").octave(1).release(.6).gain(.8)\nconst keys = chord("<Cm7 Fm7>").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").clip(.4).room(.3).gain(.5)\nstack(kick, snare, hats, sub, keys)',
           ['I7', 'I8', 'E10'], ['project', 'drums', 'bass', 'piano'], shape='project',
           challenge=task('Change the key to F minor: one edit, and both the sub and the piano follow.',
                          'const key = "F:minor" and chord("<Fm7 Bbm7>")',
                          all_(eq(KEY, 'f:minor'), inKey(sel=snd('sine')), inKey(sel=snd('piano')), some(snd('sine'), w('$pc', eq=5)))),
           challengeSolution='setcpm(92/4)\nconst key = "F:minor"\nconst kick = s("bd ~ ~ [~ bd] ~ ~ bd ~").bank("RolandTR808").gain("1 1 1 .3 1 1 1 1").swingBy(.2, 8)\nconst snare = s("~ sd ~ sd").bank("RolandTR808")\nconst hats = s("hh*16").bank("RolandTR808").gain("[.5 .25 .35 .25]*4").swingBy(.2, 8)\nconst sub = n("0 ~ ~ ~ ~ ~ 0 ~").scale(key).s("sine").octave(1).release(.6).gain(.8)\nconst keys = chord("<Fm7 Bbm7>").voicing().struct("[~ x ~ ~] [~ ~ x ~] [~ x ~ ~] [~ ~ x ~]").s("piano").clip(.4).room(.3).gain(.5)\nstack(kick, snare, hats, sub, keys)',
           summary=['A boom bap beat: half-time kick with a ghost, straight snare, swung hats, 808 sub, piano chops.', 'One const key keeps the sub and the piano in tune.', 'Drums on top; the sample sits underneath.'],
           introduces=['chord', '.scale'], concepts=['const key', 'the beat'],
           preload=kit('bd', 'sd', 'hh', bank=TR808) + [{"s": "piano"}]),
]

tracks = [track('boom-bap', 'Boom bap', 'Half-time drums, swung hats, an 808 sub and piano chops: a beat from the SP-1200 era.',
                lessons, requires=['B5', 'B10', 'I1', 'B12'], tags=['hip hop'])]

write(pack('hip-hop', 'Hip hop', 'Boom bap: the half-time kick, the drunken swing, the 808 sub and chopped piano, on the skills from the core lessons.',
           tracks, lessons, tags=['hip hop', '808', 'swing', 'piano']))
